namespace ynx::auth::mobile::receipt {
class RegisteredAccountReceipt {public:bool closed=false;int children=0;RegisteredAccountReceipt(){++f.live;}~RegisteredAccountReceipt(){assert(closed&&children==0);--f.live;}};
class ReceiptDirectoryLoan {public:std::shared_ptr<RegisteredAccountReceipt>parent;bool closed=false;explicit ReceiptDirectoryLoan(std::shared_ptr<RegisteredAccountReceipt>p):parent(std::move(p)){++parent->children;++f.dirLive;}~ReceiptDirectoryLoan(){assert(closed);--f.dirLive;}};
ReceiptAcquisition acquireOriginalRegisteredAccountReceipt()noexcept{++f.acquires;if(f.onAcquire)f.onAcquire();return {f.supply?std::make_shared<RegisteredAccountReceipt>():nullptr,f.acquireFailure,f.acquireReady,f.pending};}
ynx::core::mobile::registered::ReadResult readOriginalReceipt(const std::shared_ptr<RegisteredAccountReceipt>&p,ReceiptDATA&out)noexcept{assert(p&&!p->closed);++f.reads;if(f.readFailure.present)return {false,f.readFailure};if(f.readNotReady)return {false,{},true,f.pending};out=f.data;return {true,{}};}
ynx::core::mobile::registered::ReadResult originalReceiptCurrent(const std::shared_ptr<RegisteredAccountReceipt>&p)noexcept{assert(p&&!p->closed);int n=++f.currents;if(f.onCurrent)f.onCurrent();if(f.currentFailure.present&&(!f.failCurrentAt||n==f.failCurrentAt))return {false,f.currentFailure};if(f.currentNotReady&&(!f.notReadyCurrentAt||n==f.notReadyCurrentAt))return {false,{},true,f.pending};return {true,{}};}
void retireOriginalReceipt(const std::shared_ptr<RegisteredAccountReceipt>&p)noexcept{assert(p);++f.retires;}
Failure joinOriginalReceipt(const std::shared_ptr<RegisteredAccountReceipt>&p)noexcept{assert(p);++f.joins;return f.joinFailure;}
Failure closeOriginalReceipt(const std::shared_ptr<RegisteredAccountReceipt>&p)noexcept{assert(p);++f.closes;if(f.canClose&&p->children==0)p->closed=true;return f.closeFailure;}
bool originalReceiptClosed(const std::shared_ptr<RegisteredAccountReceipt>&p)noexcept{assert(p);return p->closed;}
ReadResult readOriginalSourceSelection(const std::shared_ptr<RegisteredAccountReceipt>&p,OriginalSourceSelection&out)noexcept{assert(p&&!p->closed);out=f.source;return {true,{}};}
DirectoryAcquisition borrowOriginalReceiptDirectory(const std::shared_ptr<RegisteredAccountReceipt>&p,uint32_t role)noexcept{assert(p&&!p->closed);auto loan=std::make_shared<ReceiptDirectoryLoan>(p);if(f.onBorrow)f.onBorrow();if(role==f.missingRole)return {loan,f.directoryFailure,true,{}};return {loan,{},true,{}};} // contradictory ready+failure must still refuse
Failure closeOriginalReceiptDirectory(const std::shared_ptr<ReceiptDirectoryLoan>&p)noexcept{assert(p);if(!p->closed){p->closed=true;--p->parent->children;}return {};}
bool originalReceiptDirectoryClosed(const std::shared_ptr<ReceiptDirectoryLoan>&p)noexcept{assert(p);return p->closed;}
}
